// More signature places with intros of their own: the great stadiums and
// arenas, the buildings that define skylines, the museums, the streets and
// markets where fashion, food and retail happen, and the places technology
// and games come from. Tagged by what they're about, so the Work map's
// industries can show their own signature places.
import type { Form, IntroPlace } from "./places";

const P = (id: string, name: string, where: string, lon: number, lat: number, size: number, tags: string[], lines: string[], facts: [string, string][], extra: Partial<IntroPlace> = {}): IntroPlace =>
  ({ id, name, where, lon, lat, size, tags, lines, facts, ...extra });

/** A stadium bowl: raked stands in tiers, a back wall, an optional roof rim, and the pitch (metres). */
const bowl = (rx: number, ry: number, ix: number, iy: number, h: number, o: { rot?: number; roof?: number; pitch?: [number, number]; tiers?: number } = {}): Form[] => [
  { f: "box", w: o.pitch?.[0] ?? ix * 1.5, d: o.pitch?.[1] ?? iy * 1.5, h: 0.6, rot: o.rot },
  { f: "stand", rx: ix + (rx - ix) * 0.55, ry: iy + (ry - iy) * 0.55, ix, iy, h: h * 0.45, n: o.tiers ?? 4, rot: o.rot },
  { f: "stand", rx: rx - 3, ry: ry - 3, ix: ix + (rx - ix) * 0.45, iy: iy + (ry - iy) * 0.45, h, n: 4, rot: o.rot },
  { f: "ring", rx, ry, ix: rx - 3, iy: ry - 3, h: h + 1, rot: o.rot },
  ...(o.roof ? [{ f: "ring" as const, rx: rx + 4, ry: ry + 4, ix: ix + o.roof * 0.2, iy: iy + o.roof * 0.2, h: 2.5, z: h + 2, rot: o.rot }] : []),
];
/** A ballpark: stands wrapped round home plate (`home`, degrees from east), low bleachers beyond the outfield, a canopy over the grandstand, light masts. */
const ballpark = (home: number, r: number, h: number, o: { field?: number; lights?: boolean } = {}): Form[] => {
  const at = (a: number, d: number) => ({ dx: Math.cos(a * Math.PI / 180) * d, dy: Math.sin(a * Math.PI / 180) * d });
  const fr = o.field ?? r * 0.62;
  return [
    { f: "cyl", r: fr, h: 0.4 },
    { f: "box", w: fr * 0.5, d: fr * 0.5, h: 0.7, rot: 45 - home, ...at(home, fr * 0.42) },
    { f: "stand", rx: r, ry: r, ix: fr, iy: fr, h, n: 5, from: home - 125, to: home + 125 },
    { f: "stand", rx: r * 0.92, ry: r * 0.92, ix: fr, iy: fr, h: h * 0.35, n: 3, from: home + 125, to: home + 235 },
    { f: "stand", rx: r + 3, ry: r + 3, ix: r - 12, iy: r - 12, h: 2.5, n: 1, z: h + 3, from: home - 115, to: home + 115 },
    ...(o.lights === false ? [] : [-100, -50, 0, 50, 100].map((a): Form => ({ f: "cyl", r: 1.2, h: h + 20, ...at(home + 180 + a * 0.9, r + 4) }))),
  ];
};
/** A tall building: a base and a shaft, optional crown and spire. */
const tower = (w: number, d: number, h: number, o: { base?: number; crown?: number; spire?: number; rot?: number } = {}): Form[] => [
  ...(o.base ? [{ f: "box" as const, w: w * 1.6, d: d * 1.6, h: o.base, rot: o.rot }] : []),
  { f: "box", w, d, h, z: 0, rot: o.rot },
  ...(o.crown ? [{ f: "frustum" as const, w: w * 0.8, top: w * 0.3, h: o.crown, z: h }] : []),
  ...(o.spire ? [{ f: "cyl" as const, r: 1.5, top: 0.3, h: o.spire, z: h + (o.crown ?? 0) }] : []),
];

